(x, y, t) => {
  let nx = x / 480, ny = y / 240;
  let f1 = 0, f2 = 0, f3 = 0;
  let src = [
    [0.3+0.15*Math.sin(t*0.7), 0.4+0.2*Math.cos(t*0.5)],
    [0.7+0.1*Math.cos(t*0.6), 0.6+0.15*Math.sin(t*0.8)],
    [0.5+0.2*Math.sin(t*0.4), 0.3+0.1*Math.cos(t*0.9)],
    [0.2+0.12*Math.cos(t*0.55), 0.7+0.18*Math.sin(t*0.45)],
    [0.8+0.08*Math.sin(t*0.65), 0.2+0.12*Math.cos(t*0.75)],
    [0.5+0.1*Math.sin(t*0.35), 0.8+0.1*Math.cos(t*0.6)],
    [0.15+0.18*Math.cos(t*0.5), 0.15+0.15*Math.sin(t*0.7)]
  ];
  for (let i = 0; i < 7; i++) {
    let dx = nx-src[i][0], dy = ny-src[i][1];
    let d = Math.sqrt(dx*dx+dy*dy);
    let a = 1/(1+d*6);
    f1 += Math.sin(d*38-t*2.2+i*0.9)*a;
    f2 += Math.cos(d*33+t*1.7+i*1.1)*a;
    f3 += Math.sin(d*42+t*1.9+i*0.7+1.57)*a;
  }
  let r1 = Math.sin(f1*3+f2)*Math.cos(f2*2.5+f3);
  let r2 = Math.cos(f1*2+f3*1.5)*Math.sin(f2*3-f1);
  let r3 = Math.sin(f3*2.5+f1)*Math.cos(f1*1.5+f2*2);
  let p1 = (f1+r1)*0.5, p2 = (f2+r2)*0.5, p3 = (f3+r3)*0.5;
  let blend = (p1+p2+p3)/3;
  let edge = Math.abs(Math.sin(p1*4)*Math.cos(p2*3.5)*Math.sin(p3*3));
  let h = blend * 2.5 + t * 0.08;
  let sat = 0.7 + 0.3 * Math.sin(blend * 5);
  let r = 0.5+0.48*Math.sin(h*2.094+0.5)*sat;
  let g = 0.5+0.48*Math.sin(h*2.094+2.6)*sat;
  let b = 0.5+0.48*Math.sin(h*2.094+4.7)*sat;
  let glow = 0.15*edge;
  r = r*0.82+glow+0.12;
  g = g*0.72+glow*0.8+0.06;
  b = b*0.68+glow*0.6+0.18;
  return [Math.min(1,Math.max(0,r)), Math.min(1,Math.max(0,g)), Math.min(1,Math.max(0,b))];
}
